node -e '
const https = require("https");
// Google Discovery APIから forms:v1 のドキュメントを取得する
https.get("https://discovery.googleapis.com/$discovery/rest?version=v1", (res) => {
  let data = "";
  res.on("data", chunk => data += chunk);
  res.on("end", () => {
    try {
      const apis = JSON.parse(data).items;
      const formsApi = apis.find(api => api.name === "forms");
      if (formsApi) {
        console.log("Forms API Discovery URL:", formsApi.discoveryRestUrl);
        https.get(formsApi.discoveryRestUrl, (res2) => {
          let data2 = "";
          res2.on("data", chunk => data2 += chunk);
          res2.on("end", () => {
            const apiDef = JSON.parse(data2);
            console.log("Forms API Types/Schemas:");
            console.log(Object.keys(apiDef.schemas || {}));
          });
        });
      } else {
        console.log("Forms API not found in discovery list");
      }
    } catch(e) {
      console.log("Error parsing discovery:", e);
    }
  });
});
'

